1	// Package cmdsuggest renders the command-suggestion list shown under the
2	// command line (DEVDESK-89). Rendering is pure: state in, lines out.
3	package cmdsuggest
4	
5	import (
6		"fmt"
7		"image/color"
8		"strings"
9	
10		"charm.land/lipgloss/v2"
11		"github.com/charmbracelet/x/ansi"
12	
13		"github.com/anthnel/devdesk/internal/command"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// MaxVisibleRows is the ceiling on suggestion rows shown at once.
18	const MaxVisibleRows = 8
19	
20	// Row is one suggestion; Current marks the view that is open now.
21	type Row struct {
22		Entry   command.Entry
23		Current bool
24		// Arg, when non-nil, makes this an argument row: Entry is ignored.
25		Arg *command.ArgSuggestion
26	}
27	
28	// Input is everything Render needs.
29	type Input struct {
30		Rows   []Row
31		Total  int
32		Query  string
33		Cursor int // -1 means no highlighted row
34		Offset int
35		Notice string
36		// Heading replaces the "N of M" count in the filet (argument stage).
37		Heading string
38		// Empty is the message shown when there are no rows and Loading is false.
39		Empty string
40		// Loading shows "Loading contexts…" in place of the rows.
41		Loading bool
42		Width   int
43		Visible int
44	}
45	
46	// Layout holds column widths in cells.
47	type Layout struct{ Marker, Name, Alias, Desc int }
48	
49	// Pair is a foreground/background combination the list paints.
50	type Pair struct {
51		Name   string
52		Fg, Bg color.Color
53	}
54	
55	// Layout constants, in cells. The widths below are the whole grid: a line is
56	// a border, a one-cell margin, the columns, then fill up to the other border.
57	const (
58		margin        = 1
59		markerWidth   = 2
60		minDescWidth  = 20
61		minAliasWidth = 34 // narrowest terminal that still shows the alias column
62		wideWidth     = 100
63		aliasSep      = " · "
64		currentTag    = "(current)"
65		ellipsis      = "…"
66		// minNoteWidth is the narrowest note column worth drawing; below it the
67		// note disappears before the name or the (current) tag lose a cell.
68		minNoteWidth = 8
69		loadingText  = "Loading contexts…"
70		// minRenderWidth is the narrowest width that holds a frame, a margin, a
71		// marker and one name cell.
72		minRenderWidth = 6
73	)
74	
75	// Window returns the first visible row so that cursor stays in view. The
76	// window never wraps and, with no highlighted row, keeps the current offset.
77	func Window(cursor, offset, visible int) int {
78		offset = max(offset, 0)
79		if cursor < 0 || visible <= 0 {
80			return offset
81		}
82		switch {
83		case cursor < offset:
84			return cursor
85		case cursor >= offset+visible:
86			return cursor - visible + 1
87		}
88		return offset
89	}
90	
91	// Columns returns the column widths for a terminal width. Columns leave from
92	// the right: description first, then alias; the name alone remains.
93	func Columns(width int) Layout {
94		l := Layout{Marker: markerWidth}
95		if width < minAliasWidth {
96			l.Name = max(width-6, 1)
97			return l
98		}
99		l.Name, l.Alias = 15, 14
100		if width >= wideWidth {
101			l.Name, l.Alias = 18, 18
102		}
103		if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
104			l.Desc = desc
105		}
106		return l
107	}
108	
109	// first returns the index of the first row drawn, kept inside the list.
110	func first(in Input) int {
111		return max(min(in.Offset, len(in.Rows)-max(in.Visible, 0)), 0)
112	}
113	
114	// FiletLabel returns the text of the bottom rule: the notice as a warning
115	// when there is one, otherwise the count with what scrolled out of view.
116	func FiletLabel(in Input) string {
117		if in.Notice != "" {
118			return theme.IconWarning + " " + in.Notice
119		}
120		in.Visible = max(in.Visible, 0)
121		label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
122		switch {
123		case in.Heading != "":
124			label = in.Heading
125		case strings.TrimSpace(in.Query) == "":
126			label = fmt.Sprintf("%d available", len(in.Rows))
127		}
128		if in.Visible == 0 {
129			// No row is drawn, so nothing can be announced as hidden.
130			return label
131		}
132		start := first(in)
133		if above := start; above > 0 {
134			label += fmt.Sprintf(" · ▲ %d more", above)
135		}
136		if below := len(in.Rows) - start - in.Visible; below > 0 {
137			label += fmt.Sprintf(" · ▼ %d more", below)
138		}
139		return label
140	}
141	
142	// look is one foreground/background combination, read from the theme at call
143	// time so that a theme applied after start-up is honored.
144	type look struct {
145		name string
146		fg   color.Color
147		bg   color.Color
148		bold bool
149	}
150	
151	func (k look) style() lipgloss.Style {
152		return lipgloss.NewStyle().Foreground(k.fg).Background(k.bg).Bold(k.bold)
153	}
154	
155	func rowLook() look {
156		return look{name: "row", fg: theme.ColorText, bg: theme.ColorBackground}
157	}
158	
159	func highlightLook() look {
160		return look{name: "highlighted row", fg: theme.ColorText, bg: theme.ColorTableLineSelected, bold: true}
161	}
162	
163	func argNoteLook() look {
164		return look{name: "argument note", fg: theme.ColorText, bg: theme.ColorBackground}
165	}
166	
167	func highlightedArgNoteLook() look {
168		return look{name: "highlighted argument note", fg: theme.ColorText, bg: theme.ColorTableLineSelected}
169	}
170	
171	func messageLook() look {
172		return look{name: "message", fg: theme.ColorText, bg: theme.ColorBackground}
173	}
174	
175	func filetLook() look {
176		return look{name: "filet label", fg: theme.ColorText, bg: theme.ColorBackground}
177	}
178	
179	func warningLook() look {
180		return look{name: "filet warning", fg: theme.ColorFooterWarn, bg: theme.ColorBackground, bold: true}
181	}
182	
183	// Palette lists every text pair the list paints, for the contrast test. The
184	// frame characters are decoration and carry no information, so they are not
185	// listed.
186	func Palette() []Pair {
187		var out []Pair
188		for _, k := range []look{rowLook(), highlightLook(), argNoteLook(), highlightedArgNoteLook(), messageLook(), filetLook(), warningLook(), titleLook(), inputLook()} {
189			out = append(out, Pair{Name: k.name, Fg: k.fg, Bg: k.bg})
190		}
191		return out
192	}
193	
194	// Render returns Visible list rows followed by the bottom rule, each exactly
195	// Width cells wide. Every line is assembled from separately styled segments;
196	// no already-styled text is ever cut.
197	func Render(in Input) []string {
198		return renderWith(in, theme.ColorViewportBorder)
199	}
200	
201	// renderWith is Render with the border color chosen by the caller: the
202	// palette draws its frame in ColorPaletteBorder.
203	func renderWith(in Input, borderColor color.Color) []string {
204		in.Visible = max(in.Visible, 0)
205		if in.Width < minRenderWidth {
206			return degenerate(in, borderColor)
207		}
208		inner := max(in.Width-2, 0)
209		layout := Columns(in.Width)
210		border := lipgloss.NewStyle().Foreground(borderColor).Background(theme.ColorBackground)
211		side := border.Render("│")
212	
213		lines := make([]string, 0, in.Visible+1)
214		if len(in.Rows) == 0 {
215			for i := 0; i < in.Visible; i++ {
216				body := theme.EmptyLineBg(inner)
217				if i == 0 {
218					body = row(emptyText(in), layout, inner, false)
219				}
220				lines = append(lines, side+body+side)
221			}
222		} else {
223			start := first(in)
224			for i := 0; i < in.Visible; i++ {
225				idx := start + i
226				if idx >= len(in.Rows) {
227					lines = append(lines, side+theme.EmptyLineBg(inner)+side)
228					continue
229				}
230				lines = append(lines, side+row(columnsOf(in.Rows[idx], layout, inner), layout, inner, idx == in.Cursor)+side)
231			}
232		}
233		return append(lines, filet(in, inner, border))
234	}
235	
236	// degenerate renders the lines of a terminal too narrow for a frame: blank
237	// background lines and a bare rule, each exactly Width cells (possibly zero).
238	func degenerate(in Input, borderColor color.Color) []string {
239		w := max(in.Width, 0)
240		lines := make([]string, 0, in.Visible+1)
241		for i := 0; i < in.Visible; i++ {
242			lines = append(lines, theme.EmptyLineBg(w))
243		}
244		rule := lipgloss.NewStyle().Foreground(borderColor).Background(theme.ColorBackground)
245		return append(lines, rule.Render(strings.Repeat("─", w)))
246	}
247	
248	// cells is the plain text of each column of one row.
249	// A message spans every column.
250	type cells struct {
251		name, alias, desc, message string
252		// arg marks an argument row: name and desc arrive already fitted.
253		arg bool
254	}
255	
256	// emptyText returns the message of a list with no rows: loading wins, then the
257	// caller's own wording, then the command stage's "No match".
258	func emptyText(in Input) cells {
259		switch {
260		case in.Loading:
261			return cells{message: loadingText}
262		case in.Empty != "":
263			return cells{message: in.Empty}
264		}
265		return cells{message: fmt.Sprintf("No match for %q", in.Query)}
266	}
267	
268	// columnsOf returns the plain text of a row for a layout. The current marker
269	// leads the description, or stands in for the aliases when the description
270	// is hidden; it is dropped when neither column exists.
271	func columnsOf(r Row, l Layout, inner int) cells {
272		if r.Arg != nil {
273			return argCells(r, l, inner)
274		}
275		c := cells{
276			name:  r.Entry.Label(),
277			alias: strings.Join(r.Entry.Aliases, aliasSep),
278			desc:  r.Entry.Description,
279		}
280		if r.Current {
281			switch {
282			case l.Desc > 0:
283				c.desc = strings.TrimSpace(currentTag + " " + c.desc)
284			case l.Alias > 0:
285				c.alias = currentTag
286			}
287		}
288		return c
289	}
290	
291	// fit truncates plain text to leave one cell of air inside its column and
292	// pads it to the full width.
293	func fit(text string, width int) string {
294		if width <= 0 {
295			return ""
296		}
297		if lipgloss.Width(text) > width-1 {
298			text = ansi.Truncate(text, max(width-1, 1), ellipsis)
299		}
300		return text + strings.Repeat(" ", max(width-lipgloss.Width(text), 0))
301	}
302	
303	// argCells lays out an argument row: the value, then " (current)" glued to
304	// it, then the note. A long value gives way first, and the note disappears
305	// before either. The tag is kept whole only while the row has room for it
306	// (about 12 cells and more); below that the final fit() cuts the line.
307	func argCells(r Row, l Layout, inner int) cells {
308		avail := max(inner-margin-markerWidth, 0)
309		text := r.Arg.Value
310		if r.Current {
311			tag := " " + currentTag
312			if room := avail - lipgloss.Width(tag) - 1; lipgloss.Width(text) > room {
313				text = ansi.Truncate(text, max(room, 1), ellipsis)
314			}
315			text += tag
316		}
317		nameCol := min(max(lipgloss.Width(text)+1, l.Name), avail)
318		c := cells{name: fit(text, nameCol), arg: true}
319		if noteW := avail - nameCol; r.Arg.Note != "" && noteW >= minNoteWidth {
320			c.desc = fit(r.Arg.Note, noteW)
321		}
322		return c
323	}
324	
325	// row assembles one list line from styled segments, filled up to inner cells.
326	// A highlighted row fills with its own background so it reaches the border.
327	func row(c cells, l Layout, inner int, highlighted bool) string {
328		k, note, marker := rowLook(), argNoteLook(), strings.Repeat(" ", markerWidth)
329		if highlighted {
330			k, note, marker = highlightLook(), highlightedArgNoteLook(), theme.IconCircleSmall+" "
331		}
332		if c.message != "" {
333			k = messageLook()
334			marker = strings.Repeat(" ", markerWidth)
335		}
336		if c.arg {
337			return argLine(c, inner, k, note, marker)
338		}
339		body := fit(c.name, l.Name) + fit(c.alias, l.Alias) + fit(c.desc, l.Desc)
340		if c.message != "" {
341			body = fit(c.message, max(inner-margin-markerWidth, 0))
342		}
343		return k.style().Render(padTo(strings.Repeat(" ", margin)+marker+body, inner))
344	}
345	
346	// argLine renders an argument row as two segments, the name and the note, so
347	// the note can carry its own look.
348	func argLine(c cells, inner int, k, note look, marker string) string {
349		head := strings.Repeat(" ", margin) + marker + c.name
350		if c.desc == "" {
351			return k.style().Render(padTo(head, inner))
352		}
353		return k.style().Render(head) + note.style().Render(padTo(c.desc, inner-lipgloss.Width(head)))
354	}
355	
356	// padTo pads plain text with spaces up to width cells.
357	func padTo(plain string, width int) string {
358		return plain + strings.Repeat(" ", max(width-lipgloss.Width(plain), 0))
359	}
360	
361	// filet builds the bottom rule with its label.
362	func filet(in Input, inner int, border lipgloss.Style) string {
363		const left, right = "└", "┘"
364		k := filetLook()
365		if in.Notice != "" {
366			k = warningLook()
367		}
368		label := ansi.Truncate(FiletLabel(in), max(inner-3, 0), ellipsis)
369		dashes := max(inner-2-lipgloss.Width(label)-1, 0)
370		return border.Render(left+"─ ") + k.style().Render(label) +
371			border.Render(" "+strings.Repeat("─", dashes)+right)
372	}
